#!/usr/bin/env node
/**
 * What is inside each chunk of a production build, by source folder / package (from the source maps).
 *
 *   npx vite build --sourcemap --outDir dist/map && node scripts/bundle-report.mjs dist/map [chunk-name-prefix ...]
 *
 * With no chunk names: the entry chunk (the one index.html loads) and everything it statically imports.
 * Sizes are generated bytes attributed to each source (an approximation: a source's bytes span from its first
 * mapped segment to the next one).
 */
import fs from 'node:fs';
import path from 'node:path';

const dir = process.argv[2] ?? 'dist';
const wanted = process.argv.slice(3);
const assets = path.join(dir, 'assets');
const B64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
const val = new Map([...B64].map((c, i) => [c, i]));

function perSource(file) {
  const code = fs.readFileSync(path.join(assets, file), 'utf8').split('\n');
  const map = JSON.parse(fs.readFileSync(path.join(assets, file + '.map'), 'utf8'));
  const lines = map.mappings.split(';');
  const sizes = new Map();
  // fields[1] (source index) is relative across the whole map; col resets per line.
  let src = 0;
  for (let l = 0; l < lines.length; l++) {
    let col = 0;
    const segs = [];
    for (const seg of lines[l].split(',')) {
      if (!seg) continue;
      let shift = 0;
      let acc = 0;
      const nums = [];
      for (let i = 0; i < seg.length; i++) {
        const v = val.get(seg[i]);
        acc += (v & 31) << shift;
        if (v & 32) shift += 5;
        else {
          nums.push(acc & 1 ? -(acc >> 1) : acc >> 1);
          acc = 0;
          shift = 0;
        }
      }
      col += nums[0];
      if (nums.length > 1) src += nums[1];
      segs.push({ col, src: nums.length > 1 ? src : -1 });
    }
    const len = (code[l] ?? '').length;
    for (let s = 0; s < segs.length; s++) {
      const end = s + 1 < segs.length ? segs[s + 1].col : len;
      const name = segs[s].src >= 0 ? map.sources[segs[s].src] : '(unmapped)';
      sizes.set(name, (sizes.get(name) ?? 0) + Math.max(0, end - segs[s].col));
    }
  }
  return sizes;
}

function group(name) {
  const n = name.replace(/^(\.\.\/)+/, '');
  const m = n.match(/node_modules\/((?:@[^/]+\/)?[^/]+)/);
  if (m) return 'npm:' + m[1];
  const f = n.match(/^src\/ui\/features\/([^/]+)/);
  if (f) return 'src/ui/features/' + f[1];
  const p = n.match(/^src\/plugins\/builtin\/([^/]+)/);
  if (p) return 'src/plugins/builtin/' + p[1];
  const a = n.match(/^src\/app\/([^/]+)\//);
  if (a) return 'src/app/' + a[1];
  const c = n.match(/^src\/(core|engine|sdk|ui|app|platform|plugins)\/([^/]+)/);
  if (c) return `src/${c[1]}/${c[2].includes('.') ? '(files)' : c[2]}`;
  return n.split('/').slice(0, 2).join('/');
}

const html = fs.readFileSync(path.join(dir, 'index.html'), 'utf8');
const entry = html.match(/assets\/(index-[^"]+\.js)/)[1];
function imports(file, seen = new Set()) {
  if (seen.has(file)) return seen;
  seen.add(file);
  const code = fs.readFileSync(path.join(assets, file), 'utf8');
  // static imports only: `from"./x.js"` and `import"./x.js"` at the top of the chunk
  for (const m of code.matchAll(/(?:from|import)\s*"\.\/([^"]+\.js)"/g)) {
    // dynamic imports look like import("./x.js"): those have a paren, skip them
    const before = code.slice(Math.max(0, m.index - 1), m.index + 1);
    if (/import\s*"/.test(m[0]) || /from\s*"/.test(m[0])) imports(m[1], seen);
    void before;
  }
  return seen;
}
const chunks = wanted.length
  ? fs.readdirSync(assets).filter((f) => f.endsWith('.js') && wanted.some((w) => f.startsWith(w)))
  : [...imports(entry)];
const total = new Map();
const files = new Map();
let all = 0;
for (const c of chunks) {
  if (!fs.existsSync(path.join(assets, c + '.map'))) continue;
  const sizes = perSource(c);
  let sum = 0;
  for (const [n, s] of sizes) {
    files.set(n, (files.get(n) ?? 0) + s);
    total.set(group(n), (total.get(group(n)) ?? 0) + s);
    sum += s;
  }
  all += sum;
  console.log(`chunk ${c.padEnd(40)} ${(sum / 1024).toFixed(0).padStart(6)} kB`);
}
console.log(`\ntotal ${(all / 1024).toFixed(0)} kB in ${chunks.length} chunks; by group:`);
for (const [g, s] of [...total].sort((a, b) => b[1] - a[1]).slice(0, 60)) console.log(`${(s / 1024).toFixed(1).padStart(8)} kB  ${g}`);

if (process.env.FILES) {
  console.log('\nlargest source files:');
  for (const [f, s] of [...files].sort((a, b) => b[1] - a[1]).slice(0, Number(process.env.FILES))) console.log(`${(s / 1024).toFixed(1).padStart(8)} kB  ${f.replace(/^(\.\.\/)+/, '')}`);
}
